/** How long a claimed job stays invisible to other consumers. */
export const DEFAULT_VISIBILITY_MS = 60_000;

export interface Claim {
  jobId: string;
  consumerId: string;
  claimedAt: number;
  visibilityMs: number;
}

export function isExpired(claim: Claim, now: number): boolean {
  return now - claim.claimedAt >= claim.visibilityMs;
}

export function extend(claim: Claim, extraMs: number): Claim {
  return { ...claim, visibilityMs: claim.visibilityMs + extraMs };
}

