import { DEFAULT_VISIBILITY_MS, isExpired, type Claim } from "./visibility.js";

export interface Job {
  id: string;
  payload: string;
  attempts: number;
}

export class Consumer {
  private readonly claims = new Map<string, Claim>();

  constructor(readonly id: string, readonly visibilityMs = DEFAULT_VISIBILITY_MS) {}

  claim(job: Job, now: number): Claim {
    const claim = { jobId: job.id, consumerId: this.id, claimedAt: now, visibilityMs: this.visibilityMs };
    this.claims.set(job.id, claim);
    return claim;
  }

  acknowledge(jobId: string): boolean {
    return this.claims.delete(jobId);
  }

  reclaimable(now: number): string[] {
    return [...this.claims.values()].filter((claim) => isExpired(claim, now)).map((claim) => claim.jobId);
  }
}

