export interface Counters {
  claimed: number;
  acknowledged: number;
  redelivered: number;
}

const counters: Counters = { claimed: 0, acknowledged: 0, redelivered: 0 };

export function record(event: keyof Counters): void {
  counters[event] += 1;
}

/** Snapshot for the dashboard scrape. */
export function snapshot(): Counters {
  return { ...counters };
}
